	@Test
	void bulkLoadPreservesZeroFractionIdsAndQueriesAcrossReopen() throws Exception {
		Path target = directory.toPath().resolve("bulk-zero-fractions");
		String input = """
				<urn:date:subject:0> <urn:date:value> "2023-01-15T10:30:00.0Z"^^<http://www.w3.org/2001/XMLSchema#dateTime> .
				<urn:date:subject:1> <urn:date:value> "2023-01-15T10:30:00.00Z"^^<http://www.w3.org/2001/XMLSchema#dateTime> .
				<urn:date:subject:2> <urn:date:value> "2023-01-15T10:30:00.000Z"^^<http://www.w3.org/2001/XMLSchema#dateTime> .
				""";
		LmdbBulkLoader.Result result = LmdbBulkLoader.builder(target, config())
				.partitionCount(2)
				.workers(1)
				.memoryBudgetBytes(16L * 1024 * 1024)
				.build()
				.load(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)), "urn:date:",
						RDFFormat.NTRIPLES);
		assertThat(result.parsedStatements()).isEqualTo(3);
		assertThat(result.storedStatements()).isEqualTo(3);

		StoreProperties properties = new StoreProperties(target.toFile());
		assertThat(properties.load()).isTrue();
		assertThat(properties.getVersion()).isEqualTo("6");
		assertThat(properties.usesZeroFractionDateTimeIds()).isTrue();

		List<Literal> literals = zeroFractions();
		List<String> expectedLabels = literals.stream().map(Literal::getLabel).sorted().toList();
		List<Long> initialIds = null;
		for (int reopen = 0; reopen < 2; reopen++) {
			SailRepository repository = new SailRepository(new LmdbStore(target.toFile(), config()));
			try {
				List<Long> ids = new ArrayList<>();
				try (SailRepositoryConnection connection = repository.getConnection()) {
					assertThat(connection.size()).isEqualTo(3);
					for (int i = 0; i < literals.size(); i++) {
						Literal literal = literals.get(i);
						assertThat(connection.hasStatement(subject(i), PREDICATE, literal, false)).isTrue();
						try (var statements = connection.getStatements(subject(i), PREDICATE, null, false)) {
							Literal stored = (Literal) statements.next().getObject();
							assertThat(stored.getLabel()).isEqualTo(literal.getLabel());
							long id = ((LmdbValue) stored).getInternalID();
							assertThat(ValueIds.isInlined(id)).isTrue();
							ids.add(id);
							assertThat(statements.hasNext()).isFalse();
						}
					}
				}
				assertThat(ids).doesNotHaveDuplicates();
				if (initialIds == null) {
					initialIds = List.copyOf(ids);
				} else {
					assertThat(ids).containsExactlyElementsOf(initialIds);
				}
				assertBulkQueries(repository, expectedLabels);
			} finally {
				repository.shutDown();
			}
		}
	}

	@Test
	void zeroFractionDateTimesWithNormalizedZeroTimezoneStayDictionaryBacked() throws Exception {
		List<Literal> literals = List.of(
				VF.createLiteral(DATE_TIME + ".0+00:00", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".00+00:00", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".000+00:00", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".0-00:00", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".00-00:00", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".000-00:00", XSD.DATETIME));
		LmdbStore store = new LmdbStore(directory, config());
		store.init();
		long[] ids = new long[literals.size()];
		try {
			ValueStore valueStore = (ValueStore) store.getValueFactory();
			for (int i = 0; i < literals.size(); i++) {
				ids[i] = valueStore.getId(literals.get(i), true);
				assertThat(ValueIds.isInlined(ids[i])).as(literals.get(i).getLabel()).isFalse();
			}
		} finally {
			store.shutDown();
		}

		StoreProperties properties = new StoreProperties(directory);
		assertThat(properties.load()).isTrue();
		assertThat(properties.usesZeroFractionDateTimeIds()).isTrue();
		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try {
			ValueStore valueStore = (ValueStore) reopened.getValueFactory();
			for (int i = 0; i < literals.size(); i++) {
				long id = valueStore.getId(literals.get(i));
				assertThat(id).isEqualTo(ids[i]);
				assertThat(ValueIds.isInlined(id)).isFalse();
				Literal stored = (Literal) valueStore.getValue(id);
				assertThat(stored.getLabel()).isEqualTo(literals.get(i).getLabel());
				assertThat(stored).isEqualTo(literals.get(i));
			}
		} finally {
			reopened.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo")
				.setNativeEvaluationEnabled(true)
				.setAutoGrow(true);
	}

	private static List<Literal> zeroFractions() {
		return List.of(VF.createLiteral(DATE_TIME + ".0Z", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".00Z", XSD.DATETIME),
				VF.createLiteral(DATE_TIME + ".000Z", XSD.DATETIME));
	}

	private static IRI subject(int index) {
		return VF.createIRI("urn:date:subject:" + index);
	}

	private static TripleTerm nested(Literal literal) {
		return VF.createTripleTerm(subject(9), PREDICATE, VF.createTripleTerm(subject(8), PREDICATE, literal));
	}

	private static void addStatements(SailRepositoryConnection connection) {
		for (int i = 0; i < zeroFractions().size(); i++) {
			Literal literal = zeroFractions().get(i);
			connection.add(subject(i), PREDICATE, literal);
			connection.add(subject(i), VF.createIRI("urn:date:nested"), nested(literal));
		}
	}

	private static void assertQueries(SailRepository repository, boolean newInlineEncoding, long[] expectedIds) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			for (boolean nativeEnabled : new boolean[] { false, true }) {
				System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
				try (SailRepositoryConnection connection = repository.getConnection()) {
					List<Long> ids = new ArrayList<>();
					for (int i = 0; i < zeroFractions().size(); i++) {
						Literal literal = zeroFractions().get(i);
						assertThat(connection.hasStatement(subject(i), PREDICATE, literal, false)).isTrue();
						assertThat(connection.hasStatement(subject(i), VF.createIRI("urn:date:nested"), nested(literal),
								false)).isTrue();
						try (var statements = connection.getStatements(null, PREDICATE, literal, false)) {
							Literal stored = (Literal) statements.next().getObject();
							assertThat(stored).isEqualTo(literal);
							long id = ((LmdbValue) stored).getInternalID();
							ids.add(id);
							if (expectedIds != null) {
								assertThat(id).isEqualTo(expectedIds[i]);
							} else {
								assertThat(ValueIds.isInlined(id)).isEqualTo(newInlineEncoding);
							}
							assertThat(statements.hasNext()).isFalse();
						}
					}
					assertThat(ids).doesNotHaveDuplicates();
					String anchor = "\"" + DATE_TIME + ".000Z\"^^xsd:dateTime";
					List<BindingSet> results = QueryResults.asList(connection.prepareTupleQuery(PREFIX
							+ "SELECT ?d ?sec ?same WHERE { ?s <urn:date:value> ?d . BIND(SECONDS(?d) AS ?sec) "
							+ "BIND(sameTerm(?d, " + anchor + ") AS ?same) FILTER(?d >= " + anchor
							+ " && ?d <= " + anchor + ") } ORDER BY STR(?d)").evaluate());
					assertThat(results).hasSize(3);
					for (BindingSet row : results) {
						assertThat(((Literal) row.getValue("sec")).getLabel()).isEqualTo("0.0");
						assertThat(((Literal) row.getValue("same")).booleanValue())
								.isEqualTo(((Literal) row.getValue("d")).getLabel().equals(DATE_TIME + ".000Z"));
					}
					assertThat(QueryResults.asList(connection.prepareTupleQuery(PREFIX
							+ "SELECT ?d WHERE { ?s <urn:date:value> ?d FILTER(?d = " + anchor + ") }").evaluate()))
									.hasSize(3);
				}
			}
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static void assertBulkQueries(SailRepository repository, List<String> expectedLabels) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			for (boolean nativeEnabled : new boolean[] { false, true }) {
				System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
				try (SailRepositoryConnection connection = repository.getConnection()) {
					List<BindingSet> results = QueryResults.asList(connection.prepareTupleQuery(PREFIX
							+ "SELECT ?d ?seconds WHERE { ?s <urn:date:value> ?d . BIND(SECONDS(?d) AS ?seconds) } "
							+ "ORDER BY STR(?d)").evaluate());
					assertThat(results).hasSize(3);
					List<String> labels = new ArrayList<>();
					for (BindingSet result : results) {
						labels.add(((Literal) result.getValue("d")).getLabel());
						assertThat(((Literal) result.getValue("seconds")).getLabel()).isEqualTo("0.0");
					}
					assertThat(labels).containsExactlyElementsOf(expectedLabels);
				}
			}
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
